from typing import List

def minTime(s: str, order: List[int], k: int) -> int:
    n = len(s)
    total = n * (n + 1) // 2

    def valid(t):
        star = [False] * n
        for i in range(t + 1):
            star[order[i]] = True
        nostar = 0
        run = 0
        for i in range(n):
            if star[i]:
                nostar += run * (run + 1) // 2
                run = 0
            else:
                run += 1
        nostar += run * (run + 1) // 2
        return total - nostar

    lo, hi = 0, n - 1
    res = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if valid(mid) >= k:
            res = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return res
